import React from 'react';
import { Image, type ImageStyle, type StyleProp } from 'react-native';

import { strings } from '../strings';

export type WordmarkSize = 'bar' | 'auth' | 'startup';

// Metro resolves the matching `@2x` file in the same folder automatically on a high-density
// screen — see mobile/assets/brand/ (generated by scripts/generate_brand_wordmarks.mjs).
const SOURCE = {
  bar: require('../../assets/brand/wordmark-bar.png'),
  auth: require('../../assets/brand/wordmark-auth.png'),
  startup: require('../../assets/brand/startup-logo.png'),
};

// Exact pixel size of each 1x export — keeps the rendered image at its real aspect ratio without
// needing Image.getSize at runtime.
const DIMENSIONS: Record<WordmarkSize, { width: number; height: number }> = {
  bar: { width: 156, height: 28 },
  auth: { width: 267, height: 48 },
  startup: { width: 277, height: 64 },
};

type Props = {
  /** 'bar' (24-32px, the default) for slim chrome — nav bars, sheet headers, the side-menu brand
   * block. 'auth' (40-56px) for a standalone screen moment — sign-up, login, "You're all set".
   * 'startup' is the tagline version, the loading screen only. */
  size?: WordmarkSize;
  style?: StyleProp<ImageStyle>;
};

/** The EasyKharchaLogoPlain (or, for 'startup', EasyKharchaLogoText) wordmark — replaces every
 * literal "EasyKharcha" text label on an EasyKharcha-owned surface. Never used inside a signed-in
 * business workspace's own chrome, where the business's own logo and name are the brand instead. */
export function Wordmark({ size = 'bar', style }: Props) {
  const { width, height } = DIMENSIONS[size];
  return (
    <Image
      source={SOURCE[size]}
      accessibilityLabel={strings.app.wordmark}
      resizeMode="contain"
      style={[{ width, height }, style]}
    />
  );
}
